package com.johnny.hotel.finance;import com.johnny.hotel.common.Result;import com.johnny.hotel.pagination.PageResult;import lombok.RequiredArgsConstructor;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.*;
@RestController @RequestMapping("/api/finance/daily-summaries") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('FINANCE','OWNER','SUPER_ADMIN')") public class DailyFinancialSummaryController {private final RevenueRecognitionService recognition;private final FinanceOperationsService operations;@GetMapping public Result<PageResult<DailyFinancialSummary>> list(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer pageSize){return Result.success(operations.summaries(from,to,page,pageSize));}@GetMapping("/{date}") public Result<DailyFinancialSummary> one(@PathVariable LocalDate date){return Result.success(recognition.summary(date));}}
